\documentclass[11pt]{amsart}
\usepackage{amsmath,amssymb,amsthm}
\usepackage[margin=1in]{geometry}
\usepackage{hyperref}

\theoremstyle{plain}
\newtheorem{theorem}{Theorem}[section]
\newtheorem{corollary}[theorem]{Corollary}
\theoremstyle{definition}
\newtheorem{definition}[theorem]{Definition}

\newcommand{\W}{W}
\newcommand{\N}{\mathbb{N}}
\DeclareMathOperator{\intr}{int}

\title{The Modal Logic and Alexandrov Topology of the Forcing Multiverse}
\author{Aristotle}
\date{2026-07-14}

\begin{document}

\begin{abstract}
We study the combinatorial and topological core of the modal logic of forcing in the
set-theoretic multiverse. Modeling worlds as a Kripke frame with an accessibility relation
$R$ read as ``is a forcing extension of,'' we equip assertions with the necessity operator
$\Box$ (``true in every extension'') and possibility operator $\Diamond$ (``true in some
extension''). We establish the full Sahlqvist correspondence between the modal axioms
$\mathbf{T},\mathbf{4},\mathbf{B},\mathbf{5},\mathbf{.2}$ and the frame conditions
reflexivity, transitivity, symmetry, the Euclidean property, and directedness, each as an
exact biconditional. Instantiating with $(\N,\le)$ yields a faithful model validating
$\mathsf{S4.2}$ while refuting $\mathsf{S5}$, exhibiting the loss of symmetry as the precise
mechanism separating the Hamkins--L\"owe logic of forcing from $\mathsf{S5}$. We develop the
button/switch dichotomy, count independent sentences over $n$ atoms
($2^{2^n}-2$, with proportion tending to $1$), and build the bridge to topology: the
upward-closed assertions form the Alexandrov topology of $R$; over a preorder $\Box$ is the
interior operator and $\Diamond$ the closure operator; buttons are exactly the open sets,
settled assertions exactly the clopen sets; the space is Alexandrov-discrete; and in the
fully connected multiverse the only clopen sets are the two constants.
\end{abstract}

\maketitle

\section{Introduction}
The technique of \emph{forcing}, introduced by Cohen to establish the independence of the
Continuum Hypothesis, constructs from any model of set theory a larger model---a
\emph{forcing extension}---in which some prescribed statement holds. Iterating and
amalgamating these constructions gives the picture of a branching \emph{set-theoretic
multiverse}: a class of worlds partially ordered by extension. Hamkins and L\"owe proved that
the valid modal principles governing ``in every forcing extension'' and ``in some forcing
extension'' form exactly the modal logic $\mathsf{S4.2}$.

This paper isolates the combinatorial and topological core of that theory. We prove frame
correspondences (Section~\ref{sec:corr}), the button/switch dichotomy
(Section~\ref{sec:bs}), the counting law of independence (Section~\ref{sec:count}), and the
Alexandrov-topological unification (Section~\ref{sec:top}).

\section{Definitions}
Throughout, $\W$ is a type of \emph{worlds} and $R:\W\to\W\to\mathrm{Prop}$ an
\emph{accessibility relation}, with $R\,w\,v$ read ``$v$ is a forcing extension of $w$.'' An
\emph{assertion} is a predicate $P:\W\to\mathrm{Prop}$, identified with the set $\{w:P\,w\}$.

\begin{definition}[Modal operators]
For an assertion $P$ and world $w$,
\[
  \Box P(w) :\equiv \forall v,\ R\,w\,v \to P\,v, \qquad
  \Diamond P(w) :\equiv \exists v,\ R\,w\,v \wedge P\,v.
\]
\end{definition}

\begin{definition}[Frame conditions]
$R$ is \emph{reflexive} if $R\,w\,w$; \emph{transitive} if $R\,w\,v$ and $R\,v\,u$ imply
$R\,w\,u$; \emph{symmetric} if $R\,w\,v$ implies $R\,v\,w$; \emph{Euclidean} if $R\,w\,v$ and
$R\,w\,u$ imply $R\,v\,u$; \emph{directed} (confluent) if $R\,w\,v$ and $R\,w\,u$ imply the
existence of $t$ with $R\,v\,t$ and $R\,u\,t$. A \emph{preorder} is reflexive and transitive.
\end{definition}

\begin{definition}[Buttons, switches, settled]
An assertion $S$ is a \emph{button} if $R\,w\,v$ and $w\in S$ imply $v\in S$. It is a
\emph{switch} if from every world it can be forced true and forced false. It is
\emph{settled} if its truth value is invariant along accessibility in both directions.
\end{definition}

\section{Frame correspondences and the \texorpdfstring{$\mathsf{S4.2}/\mathsf{S5}$}{S4.2/S5} separation}
\label{sec:corr}

\begin{theorem}[T $\leftrightarrow$ reflexive]
$(\forall P\,w,\ \Box P(w)\to P\,w)$ holds iff $R$ is reflexive.
\end{theorem}
\begin{proof}[Proof sketch]
If reflexive and $\Box P(w)$, apply at $v:=w$. Conversely instantiate at $P:=R\,w\,(\cdot)$ to
extract $R\,w\,w$.
\end{proof}

\begin{theorem}[4 $\leftrightarrow$ transitive]
$(\forall P\,w,\ \Box P(w)\to\Box\Box P(w))$ holds iff $R$ is transitive.
\end{theorem}
\begin{proof}[Proof sketch]
Transitivity propagates $\Box P(w)$ two steps; the converse instantiates at $P:=R\,w\,(\cdot)$.
\end{proof}

\begin{theorem}[B $\leftrightarrow$ symmetric]
$(\forall P\,w,\ P\,w\to\Box\Diamond P(w))$ holds iff $R$ is symmetric.
\end{theorem}
\begin{proof}[Proof sketch]
If symmetric and $w\in P$, any $v$ with $R\,w\,v$ has $R\,v\,w$, so $\Diamond P(v)$ is
witnessed by $w$. Converse: instantiate at $P:=\{w\}$.
\end{proof}

\begin{theorem}[5 $\leftrightarrow$ Euclidean]
$(\forall P\,w,\ \Diamond P(w)\to\Box\Diamond P(w))$ holds iff $R$ is Euclidean.
\end{theorem}

\begin{theorem}[.2 $\leftrightarrow$ directed]
$(\forall P\,w,\ \Diamond\Box P(w)\to\Box\Diamond P(w))$ holds iff $R$ is directed.
\end{theorem}
\begin{proof}[Proof sketch]
If directed and $\Diamond\Box P(w)$, pick $v$ with $R\,w\,v$ and $\Box P(v)$. For any $u$ with
$R\,w\,u$, directedness yields $t$ with $R\,v\,t,R\,u\,t$; then $P\,t$ from $\Box P(v)$, so
$\Diamond P(u)$. The converse synthesizes the amalgam from a suitable instance.
\end{proof}

\begin{theorem}[Separation]
$(\N,\le)$ is reflexive, transitive, and directed, but neither symmetric nor Euclidean. Hence
$\mathbf{T},\mathbf{4},\mathbf{.2}$ hold while $\mathbf{B}$ and $\mathbf{5}$ fail.
\end{theorem}
\begin{proof}[Proof sketch]
Directedness via the maximum; symmetry fails since $0\le1$ but $1\not\le0$. Apply the
correspondences.
\end{proof}

Since $\mathsf{S5}=\mathsf{S4}+\mathbf{B}$ and $\mathsf{S4.2}=\mathsf{S4}+\mathbf{.2}$, the loss
of symmetry is exactly what drops $\mathsf{S5}$ to $\mathsf{S4.2}$: forcing is irreversible.

\section{Buttons and switches}
\label{sec:bs}

\begin{theorem}[Buttons are fixed points of necessity]
Over a reflexive frame, $S$ is a button iff $w\in S \iff \Box S(w)$ for all $w$.
\end{theorem}

\begin{theorem}[Buttons form a distributive lattice]
If $S,T$ are buttons then so are $S\cap T$ and $S\cup T$, and distributivity holds.
\end{theorem}

\begin{theorem}[Switches are non-constant assertions]
In the fully connected multiverse, $S$ is a switch iff it is non-constant.
\end{theorem}

\begin{theorem}[Switches are not non-trivial buttons]
A genuine switch is never a non-trivial button.
\end{theorem}

\section{Independence is generic}
\label{sec:count}

\begin{definition}
A \emph{branch} over $n$ atoms is a map $\mathrm{Fin}\,n\to\mathrm{Bool}$; a \emph{sentence} is
a map from branches to $\mathrm{Bool}$; a sentence is \emph{settled} if constant.
\end{definition}

\begin{theorem}[Counting]
There are $2^n$ branches, $2^{2^n}$ sentences, exactly $2$ settled sentences, and hence
$2^{2^n}-2$ independent sentences.
\end{theorem}

\begin{theorem}[Genericity]
$\dfrac{2^{2^n}-2}{2^{2^n}} = 1 - \dfrac{2}{2^{2^n}} \to 1$ as $n\to\infty$.
\end{theorem}

\section{The Alexandrov topology of the multiverse}
\label{sec:top}

\begin{definition}[Alexandrov topology]
A set is \emph{open} iff it is an upper set for $R$ ($R\,w\,v$ and $w\in S$ imply $v\in S$).
This is a topology for any $R$.
\end{definition}

\begin{theorem}[Necessity is interior]
If $R$ is a preorder, $\intr S = \{w:\Box S(w)\}$ for every $S$.
\end{theorem}
\begin{proof}[Proof sketch]
$\{w:\Box S(w)\}$ is open by transitivity and $\subseteq S$ by reflexivity, so it lies in
$\intr S$; conversely $\intr S$ is open and inside $S$, so each of its points satisfies $\Box S$.
\end{proof}

\begin{theorem}[Possibility is closure]
If $R$ is a preorder, $\overline{S} = \{w:\Diamond S(w)\}$ for every $S$.
\end{theorem}

\begin{corollary}
Over a preorder, $\Box\Box S=\Box S$, mirroring $\intr(\intr S)=\intr S$.
\end{corollary}

\begin{theorem}[Buttons are open sets]
Over a reflexive frame, $S$ is a button iff it is open.
\end{theorem}

\begin{theorem}[Settled assertions are clopen sets]
$S$ is settled iff it is clopen in the Alexandrov topology.
\end{theorem}

\begin{theorem}[Alexandrov-discreteness]
Arbitrary intersections of open sets are open.
\end{theorem}

\begin{theorem}[Fully connected multiverse is indiscrete]
If $\W$ is nonempty and $R$ total, the only clopen sets are $\varnothing$ and $\W$; equivalently
the only settled assertions are the two truth-constants.
\end{theorem}

This is the topological face of the count: ``exactly two settled sentences'' becomes
``exactly two clopen sets.''

\section{Future work}
Reconstruct $R$ from the topology via the specialization preorder; identify directedness with
topological irreducibility; prove the settled assertions form a Boolean subalgebra with dense
independent complement; realize intermediate logics as interior-operator logics; and model law
adoption as unit propagation on the implication graph.

\section{Conclusion}
Logic, combinatorics, and topology describe one object: the passage between mathematical
universes obeys $\mathsf{S4.2}$, buttons and switches form clean structures, undecidability is
generic, and the Alexandrov topology unifies all of it with necessity as interior, possibility
as closure, buttons as open sets, and the two clopen constants as the settled assertions.

\end{document}

