def frame_profile(W: List[int], R: Relation) -> Tuple[Dict[str, bool], bool, bool, bool]:
    refl = all(R(w, w) for w in W)
    trans = all((not (R(a, b) and R(b, c))) or R(a, c)
                for a in W for b in W for c in W)
    sym = all((not R(a, b)) or R(b, a) for a in W for b in W)
    eucl = all((not (R(a, b) and R(a, c))) or R(b, c)
               for a in W for b in W for c in W)
    direct = all(
        any(R(b, t) and R(c, t) for t in W)
        for a in W for b in W for c in W if R(a, b) and R(a, c)
    )
    axioms = {"T": refl, "4": trans, "B": sym, "5": eucl, ".2": direct}
    is_s42 = refl and trans and direct
    is_s5 = refl and trans and sym
    return axioms, is_s42, is_s5, (is_s42 and not is_s5)

from __future__ import annotations
from typing import Callable, List, Set

Relation = Callable[[int, int], bool]

def interior(W: List[int], R: Relation, S: Set[int]) -> Set[int]:
    return {w for w in W if all((not R(w, v)) or (v in S) for v in W)}

def closure(W: List[int], R: Relation, S: Set[int]) -> Set[int]:
    return {w for w in W if any(R(w, v) and (v in S) for v in W)}

def is_button(W: List[int], R: Relation, S: Set[int]) -> bool:
    return interior(W, R, S) == S

def is_settled(W: List[int], R: Relation, S: Set[int]) -> bool:
    comp = set(W) - S
    return is_button(W, R, S) and is_button(W, R, comp)

